mapper.select:
SELECT *
FROM sys_permission


        AND (
            INSTR(permission_code, #{query.keyword}) > 0
            OR INSTR(permission_name, #{query.keyword}) > 0
        )


        AND module = #{query.module}


        AND status = #{query.status}


ORDER BY permission_id ASC

mapper.update:
UPDATE sys_permission
SET permission_name = #{permission.permissionName},
    module = #{permission.module},
    description = #{permission.description}
WHERE permission_id = #{permission.permissionId}

